From 2e04733bad07fa08c3aa78cb46955d83e1fc0c46 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 18:27:01 +0100
Subject: [PATCH] wizard: label devices without a name as unknown devices

The Add Device list showed devices that advertise no name as a bare MAC
address with dashes, which doesn't tell the user what they are. They are
now listed as "Unknown device" followed by their address.

BUG: 428956
---
 src/wizard/pages/discover.cpp | 27 +++++++++++++++++++++------
 1 file changed, 21 insertions(+), 6 deletions(-)

diff --git a/src/wizard/pages/discover.cpp b/src/wizard/pages/discover.cpp
index 8f3786e7..a6802eb0 100644
--- a/src/wizard/pages/discover.cpp
+++ b/src/wizard/pages/discover.cpp
@@ -23,6 +23,21 @@
 #include <BluezQt/DevicesModel>
 #include <BluezQt/Manager>

+static bool displayRoleIsAddress(const QModelIndex &idx)
+{
+    return idx.data(Qt::DisplayRole).toString() == idx.data(BluezQt::DevicesModel::AddressRole).toString().replace(QLatin1Char(':'), QLatin1Char('-'));
+}
+
+static QString deviceDisplayName(const QModelIndex &idx)
+{
+    if (displayRoleIsAddress(idx)) {
+        return i18nc("@item:inlistbox Bluetooth device that has no name, %1 is its address",
+                     "Unknown device (%1)",
+                     idx.data(BluezQt::DevicesModel::AddressRole).toString());
+    }
+    return idx.data(Qt::DisplayRole).toString();
+}
+
 class DevicesProxyModel : public QSortFilterProxyModel
 {
 public:
@@ -64,6 +79,9 @@ void DevicesProxyModel::setDevicesModel(BluezQt::DevicesModel *model)
 QVariant DevicesProxyModel::data(const QModelIndex &index, int role) const
 {
     switch (role) {
+    case Qt::DisplayRole:
+        return deviceDisplayName(mapToSource(index));
+
     case Qt::DecorationRole:
         return QIcon::fromTheme(index.data(BluezQt::DevicesModel::IconRole).toString(), QIcon::fromTheme(QStringLiteral("preferences-system-bluetooth")));

@@ -74,10 +92,6 @@ QVariant DevicesProxyModel::data(const QModelIndex &index, int role) const

 bool DevicesProxyModel::lessThan(const QModelIndex &left, const QModelIndex &right) const
 {
-    auto displayRoleIsAddress = [](const QModelIndex &idx) -> bool {
-        return idx.data(Qt::DisplayRole).toString() == idx.data(BluezQt::DevicesModel::AddressRole).toString().replace(':', '-');
-    };
-
     const bool leftIsAddress = displayRoleIsAddress(left);
     const bool rightIsAddress = displayRoleIsAddress(right);

@@ -112,8 +126,9 @@ bool DevicesProxyModel::filterAcceptsRow(int sourceRow, const QModelIndex &sourc
     }

     if (!m_searchString.isEmpty()) {
-        const QString displayString = index.data(Qt::DisplayRole).toString();
-        if (!displayString.contains(m_searchString, Qt::CaseInsensitive)) {
+        const QString displayString = deviceDisplayName(index);
+        if (!displayString.contains(m_searchString, Qt::CaseInsensitive)
+            && !index.data(Qt::DisplayRole).toString().contains(m_searchString, Qt::CaseInsensitive)) {
             return false;
         }
     }
